function guideFieldValue(guides,size,field){return String(guides?.[size]?.[field]||'').replace(/"/g,'&quot;')}
function sizeChoiceGrid(selected){return `<div class="admin-choice-grid">${SIZE_OPTIONS.map(size=>`<label class="admin-choice"><input type="checkbox" name="sizes" value="${size}" ${selected.includes(size)?'checked':''} onchange="refreshVariantAdminFields()"><span>${size}</span></label>`).join('')}</div>`}
function colorChoiceGrid(selected){return `<div class="admin-choice-grid">${COLOR_OPTIONS.map(color=>`<label class="admin-choice"><input type="checkbox" name="colors" value="${color.value}" ${selected.includes(color.value)?'checked':''} onchange="refreshVariantAdminFields()"><span class="swatch" style="background:${color.tone}"></span><span>${color.en} / ${color.km}</span></label>`).join('')}</div>`}
function sizeGuideFields(selected,guides){return `<div id="size-guide-fields" class="admin-variant-fields">${SIZE_OPTIONS.map(size=>`<fieldset class="size-guide-admin" data-size-guide="${size}" ${selected.includes(size)?'':'hidden'}><legend>${size}</legend><div class="form-grid"><label class="field">${t('waist')}<input data-guide-size="${size}" data-guide-field="waist" placeholder="e.g. 70 cm" value="${guideFieldValue(guides,size,'waist')}"></label><label class="field">${t('pantsLength')}<input data-guide-size="${size}" data-guide-field="length" placeholder="e.g. 98 cm" value="${guideFieldValue(guides,size,'length')}"></label></div><label class="field">${t('recommendedHeightWeight')}<input data-guide-size="${size}" data-guide-field="recommendation" placeholder="e.g. 155–160 cm / 40–50 kg" value="${guideFieldValue(guides,size,'recommendation')}"></label></fieldset>`).join('')}</div>`}
function colorImageFields(selected,images){return `<div id="color-image-fields" class="admin-variant-fields">${COLOR_OPTIONS.map(color=>`<label class="color-image-admin" data-color-image-field="${color.value}" ${selected.includes(color.value)?'':'hidden'}><span class="swatch" style="background:${color.tone}"></span><span>${color.en} / ${color.km}</span>${images?.[color.value]?`<img src="${images[color.value]}" alt="${color.en}">`:''}<input type="file" accept="image/png,image/jpeg,image/webp" data-color-photo="${color.value}"><small>${t('colorPhoto')}</small></label>`).join('')}</div>`}
function refreshVariantAdminFields(){const form=$('#product-form');if(!form)return;const sizes=new Set([...form.querySelectorAll('input[name="sizes"]:checked')].map(x=>x.value)),colors=new Set([...form.querySelectorAll('input[name="colors"]:checked')].map(x=>x.value));form.querySelectorAll('[data-size-guide]').forEach(field=>field.hidden=!sizes.has(field.dataset.sizeGuide));form.querySelectorAll('[data-color-image-field]').forEach(field=>field.hidden=!colors.has(field.dataset.colorImageField))}
function toggleSizeField(category){const sizeField=$('#size-field'),bagField=$('#bag-charms-field'),guides=$('#size-guide-fields');if(sizeField)sizeField.hidden=category!=='clothes';if(guides)guides.hidden=category!=='clothes';if(bagField)bagField.hidden=category!=='bags';refreshVariantAdminFields()}
