function header(){return `<header class="topbar"><div class="brand">CYPRESS<span>Fashion Store</span></div><div class="top-actions"><button class="pill" onclick="setLanguage()">${state.language==='en'?'ខ្មែរ':'EN'}</button><button class="pill ${state.view==='shop'?'active':''}" onclick="showShop()">${t('shop')}</button><button class="pill ${state.view==='my-orders'?'active':''}" onclick="showMyOrders()">${t('myOrders')}</button><button class="pill ${state.view==='admin'?'active':''}" onclick="showAdmin()">${t('admin')}</button></div></header>`}
function myOrdersPage(){const orders=Array.isArray(state.myOrders)?state.myOrders:[];if(state.myOrdersLoading)return `<section class="panel"><h2>${t('orderHistory')}</h2><div class="empty">Loading…</div></section>`;if(state.myOrdersError)return `<section class="panel"><h2>${t('orderHistory')}</h2><div class="empty">${state.myOrdersError}</div></section>`;return `<section class="panel customer-orders"><h2>${t('orderHistory')}</h2>${orders.length?orders.map(order=>{const items=Array.isArray(order.items)?order.items:[];return `<article class="customer-order"><div><b>${order.order_number}</b><br><small>${new Date(order.created_at).toLocaleString()}</small></div><span class="order-status status-${order.status}">${t(`status_${order.status}`)}</span><div class="customer-order-items">${items.map(item=>`<div>${item.quantity} × ${item.name}${item.size?` · ${item.size}`:''}${item.color?` · ${colorName(item.color)}`:''}</div>`).join('')}</div><strong>${money(order.total)}</strong></article>`}).join(''):`<div class="empty">${t('noOrders')}</div>`}</section>`}
