async function showMyOrders(){state.view='my-orders';state.myOrdersLoading=true;state.myOrdersError='';render();try{const response=await fetch('/api/my-orders',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({telegramInitData:window.Telegram?.WebApp?.initData||''})});const data=await response.json().catch(()=>({}));if(!response.ok)throw Error(data.error||t('openInTelegram'));state.myOrders=Array.isArray(data.orders)?data.orders:[]}catch(error){state.myOrders=[];state.myOrdersError=error.message||t('openInTelegram')}finally{state.myOrdersLoading=false;render()}}
copy.en.status_awaiting_payment='Waiting for payment';copy.en.status_paid='Paid';copy.en.status_shipping='Shipped';copy.en.status_ready_for_pickup='Waiting to receive';copy.en.status_completed='Received';
copy.km.status_awaiting_payment='រង់ចាំការបង់ប្រាក់';copy.km.status_paid='បានបង់ប្រាក់';copy.km.status_shipping='បានដឹកចេញ';copy.km.status_ready_for_pickup='រង់ចាំទទួល';copy.km.status_completed='បានបញ្ជាក់ថាទទួលរួច';
const ORDER_STATUSES=['awaiting_payment','paid','shipping','ready_for_pickup','completed'];
function ordersAdmin(){return `<div class="panel"><h2>${t('orders')}</h2><table class="orders"><tr><th>${t('order')}</th><th>${t('customer')}</th><th>${t('total')}</th><th>${t('status')}</th></tr>${state.orders.map(order=>`<tr><td>${order.order_number}<br><small>${new Date(order.created_at).toLocaleDateString()}</small></td><td>${order.customer_name}<br><small>${order.contact}</small></td><td>${money(order.total)}</td><td><select onchange="setOrderStatus('${order.id}',this.value)">${ORDER_STATUSES.map(status=>`<option value="${status}" ${status===order.status?'selected':''}>${t(`status_${status}`)}</option>`).join('')}</select><button class="danger order-delete" onclick="deleteAdminOrder('${order.id}')">${t('delete')}</button></td></tr>`).join('')||`<tr><td colspan="4">${t('empty')}</td></tr>`}</table></div>`}
async function deleteAdminOrder(id){if(!confirm('Delete this order? / 删除这个订单吗？'))return;try{await adminFetch(`/api/admin/orders/${id}`,{method:'DELETE'});await loadAdmin();render()}catch(error){alert(error.message)}}
function myOrdersPage(){const orders=Array.isArray(state.myOrders)?state.myOrders:[];if(state.myOrdersLoading)return `<section class="panel"><h2>${t('orderHistory')}</h2><div class="empty">Loading…</div></section>`;if(state.myOrdersError)return `<section class="panel"><h2>${t('orderHistory')}</h2><div class="empty">${state.myOrdersError}</div></section>`;return `<section class="panel customer-orders"><h2>${t('orderHistory')}</h2>${orders.length?orders.map(order=>{const items=Array.isArray(order.items)?order.items:[];return `<article class="customer-order"><div><b>${order.order_number}</b><br><small>${new Date(order.created_at).toLocaleString()}</small></div><span class="order-status status-${order.status}">${t(`status_${order.status}`)}</span><div class="customer-order-items">${items.map(item=>`<div>${item.quantity} × ${item.name}${item.size?` · ${item.size}`:''}${item.color?` · ${colorName(item.color)}`:''}</div>`).join('')}</div><strong>${money(order.total)}</strong><button class="danger customer-order-delete" onclick="deleteMyOrder('${order.id}')">${t('delete')}</button></article>`}).join(''):`<div class="empty">${t('noOrders')}</div>`}</section>`}
async function deleteMyOrder(id){if(!confirm('Delete this order? / លុបការបញ្ជាទិញនេះ?'))return;try{const response=await fetch('/api/my-orders/delete',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({telegramInitData:window.Telegram?.WebApp?.initData||'',id})});if(!response.ok){const data=await response.json().catch(()=>({}));throw Error(data.error||'Could not delete order.')}await showMyOrders()}catch(error){alert(error.message)}}
copy.en.backToHome='← Back to shop';copy.km.backToHome='← ត្រឡប់ទៅហាង';
function isStoreOwner(){const owner=String(state.settings?.owner_telegram_chat_id||'');const current=String(window.Telegram?.WebApp?.initDataUnsafe?.user?.id||'');return Boolean(owner&&current&&owner===current)}
function header(){return `<header class="topbar"><button class="brand brand-button" onclick="showShop()">CYPRESS<span>Fashion Store</span></button>${isStoreOwner()?`<div class="top-actions"><button class="pill ${state.view==='admin'?'active':''}" onclick="showAdmin()">${t('admin')}</button></div>`:''}</header>`}
function customerActions(){return `<div class="customer-actions"><button class="customer-action" onclick="setLanguage()">${state.language==='en'?'ខ្មែរ':'EN'}</button><button class="customer-action" onclick="showMyOrders()">${t('myOrders')}</button></div>`}
function shop(){const list=state.category==='all'?state.products:state.products.filter(p=>p.category===state.category),hero=state.language==='km'?state.settings.hero_km:state.settings.hero_en,heroText=state.language==='km'?state.settings.hero_text_km:state.settings.hero_text_en;return `<section class="hero"><div class="hero-main"><div class="eyebrow">${t('heroTag')}</div><h1>${hero}</h1><p>${heroText}</p></div><div class="hero-side"><strong>${t('new')}</strong></div></section>${customerActions()}<div class="section-head"><h2>${t('featured')}</h2><small>${list.length} ${t('items')}</small></div><div class="filters">${['all','clothes','bags','charms'].map(x=>`<button class="filter ${state.category===x?'selected':''}" onclick="setCategory('${x}')">${t(x)}</button>`).join('')}</div><div class="products">${list.length?list.map(p=>`<article class="product"><button class="product-image product-image-button" onclick="showProduct('${p.id}')">${image(p)}</button><div class="product-body"><h3 class="product-title"><button class="title-button" onclick="showProduct('${p.id}')">${productName(p)}</button></h3><p class="description">${description(p)}</p><div class="product-meta"><span>${t(p.category)}</span><span class="product-price">${money(p.price)}</span></div><button class="add" onclick="showProduct('${p.id}')">${t('viewDetails')}</button></div></article>`).join(''):`<div class="empty">${t('noProducts')}</div>`}</div><button class="cart" onclick="showCart()">${t('bag')} · ${state.cart.reduce((n,x)=>n+x.qty,0)}</button>`}
function myOrdersPage(){const orders=Array.isArray(state.myOrders)?state.myOrders:[];if(state.myOrdersLoading)return `<section class="panel"><button class="back" onclick="showShop()">${t('backToHome')}</button><h2>${t('orderHistory')}</h2><div class="empty">Loading…</div></section>`;if(state.myOrdersError)return `<section class="panel"><button class="back" onclick="showShop()">${t('backToHome')}</button><h2>${t('orderHistory')}</h2><div class="empty">${state.myOrdersError}</div></section>`;return `<section class="panel customer-orders"><button class="back" onclick="showShop()">${t('backToHome')}</button><h2>${t('orderHistory')}</h2>${orders.length?orders.map(order=>{const items=Array.isArray(order.items)?order.items:[];return `<article class="customer-order"><div><b>${order.order_number}</b><br><small>${new Date(order.created_at).toLocaleString()}</small></div><span class="order-status status-${order.status}">${t(`status_${order.status}`)}</span><div class="customer-order-items">${items.map(item=>`<div>${item.quantity} × ${item.name}${item.size?` · ${item.size}`:''}${item.color?` · ${colorName(item.color)}`:''}</div>`).join('')}</div><strong>${money(order.total)}</strong><button class="danger customer-order-delete" onclick="deleteMyOrder('${order.id}')">${t('delete')}</button></article>`}).join(''):`<div class="empty">${t('noOrders')}</div>`}</section>`}
function admin(){return `<section><div class="section-head"><h2>${t('adminTitle')}</h2><button class="back admin-home" onclick="showShop()">${t('backToHome')}</button></div><label class="field"><b>${t('adminKey')}</b><input id="admin-key" type="password" placeholder="${t('adminKey')}" autocomplete="current-password"><small>Enter once before saving. It stays only in this open session.</small></label><div class="admin-nav">${['products','orders','settings'].map(x=>`<button class="${state.adminTab===x?'selected':''}" onclick="adminTab('${x}')">${t(x)}</button>`).join('')}</div>${state.adminTab==='products'?productAdmin():state.adminTab==='orders'?ordersAdmin():settingsAdmin()}</section>`}
copy.en.freeShipping='Free shipping on orders {amount}+';copy.km.freeShipping='ដឹកជញ្ជូនឥតគិតថ្លៃ សម្រាប់ការបញ្ជាទិញ {amount}+';
