function shop(){const list=state.category==='all'?state.products:state.products.filter(p=>p.category===state.category),hero=state.language==='km'?state.settings.hero_km:state.settings.hero_en,heroText=state.language==='km'?state.settings.hero_text_km:state.settings.hero_text_en;return `<section class="hero"><div class="hero-main"><div class="eyebrow">${t('heroTag')}</div><h1>${hero}</h1><p>${heroText}</p></div><div class="hero-side"><strong>${t('new')}</strong></div></section>${customerActions()}<div class="section-head"><h2>${t('featured')}</h2><small>${list.length} ${t('items')}</small></div><div class="filters">${['all','clothes','bags','charms'].map(x=>`<button class="filter ${state.category===x?'selected':''}" onclick="setCategory('${x}')">${t(x)}</button>`).join('')}</div><div class="products">${list.length?list.map(p=>`<article class="product product-simple"><button class="product-image product-image-button" onclick="showProduct('${p.id}')">${image(p)}</button><div class="product-body"><h3 class="product-title"><button class="title-button" onclick="showProduct('${p.id}')">${productName(p)}</button></h3><p class="product-promo">${t('freeShipping')}</p></div></article>`).join(''):`<div class="empty">${t('noProducts')}</div>`}</div><button class="cart" onclick="showCart()">${t('bag')} · ${state.cart.reduce((n,x)=>n+x.qty,0)}</button>`}
async function saveProduct(event){event.preventDefault();const form=event.currentTarget,editing=state.editId?state.products.find(p=>p.id===state.editId):null,main=form.main_photo.files[0],detail=form.detail_photo.files[0];if(!editing&&(!main||!detail)){alert('Choose both a main photo and a detail photo.');return}const input=Object.fromEntries(new FormData(form));input.sizes=[...form.querySelectorAll('input[name="sizes"]:checked')].map(x=>x.value);input.colors=[...form.querySelectorAll('input[name="colors"]:checked')].map(x=>x.value);input.excludes_charms=Boolean(form.excludes_charms?.checked);input.mainImageData=main?await toData(main):'';input.detailImageData=detail?await toData(detail):'';input.published=form.published.checked;input.featured=form.featured.checked;if(editing){input.image_url=editing.image_url;input.detail_image_url=editing.detail_image_url||''}try{await adminFetch(editing?`/api/admin/products/${editing.id}`:'/api/admin/products',{method:editing?'PATCH':'POST',body:JSON.stringify(input)});state.editId=null;await loadAdmin();render();showAdminSuccess(editing?t('saved'):t('productAdded'))}catch(error){if(error.message!=='Cancelled')alert(error.message)}}
copy.en.freeShippingThreshold='Free-shipping amount (USD)';copy.km.freeShippingThreshold='ចំនួនទឹកប្រាក់សម្រាប់ដឹកជញ្ជូនឥតគិតថ្លៃ (USD)';
copy.en.shipping='Delivery fee';copy.km.shipping='ថ្លៃដឹកជញ្ជូន';
copy.en.freeDelivery='Free delivery';copy.km.freeDelivery='ដឹកជញ្ជូនឥតគិតថ្លៃ';
copy.en.spendMore='Spend {amount} more for free delivery';copy.km.spendMore='ទិញបន្ថែម {amount} ដើម្បីដឹកជញ្ជូនឥតគិតថ្លៃ';
function shippingThreshold(){const value=Number(state.settings?.free_shipping_threshold);return Number.isFinite(value)&&value>0?value:0}
function freeShippingMessage(){const threshold=shippingThreshold();return threshold?t('freeShipping').replace('{amount}',money(threshold)):''}
function shippingFor(subtotal){if(state.delivery!=='delivery')return 0;const threshold=shippingThreshold();if(threshold&&subtotal>=threshold)return 0;return Number(String(state.settings.shipping?.[state.region]||'$0').replace('$',''))||0}
function checkout(sub){const regions=Object.keys(state.settings.shipping||{});if(!regions.includes(state.region))state.region=regions[0]||'';const threshold=shippingThreshold(),freeDelivery=state.delivery==='delivery'&&threshold&&sub>=threshold,shipping=shippingFor(sub),remaining=Math.max(0,threshold-sub);return `<div class="form-grid"><label class="field">${t('name')}<input id="customer-name"></label><label class="field">${t('contact')}<input id="customer-contact" placeholder="@username or 012…"></label></div><div class="delivery"><button class="${state.delivery==='delivery'?'selected':''}" onclick="delivery('delivery')"><b>${t('delivery')}</b><br><small>${t('deliveryHint')}</small></button><button class="${state.delivery==='pickup'?'selected':''}" onclick="delivery('pickup')"><b>${t('pickup')}</b><br><small>${state.settings.pickup}</small></button></div>${state.delivery==='delivery'?`<label class="field">${t('region')}<select onchange="region(this.value)">${regions.map(k=>`<option ${k===state.region?'selected':''}>${k}</option>`).join('')}</select></label><label class="field">${t('address')}<textarea id="customer-address" placeholder="${t('addressHint')}"></textarea></label>`:`<div class="notice">${t('pickupNotice')} ${state.settings.pickup}</div>`}${state.delivery==='delivery'?`<div class="shipping-summary"><span>${t('shipping')}</span><strong>${freeDelivery?t('freeDelivery'):money(shipping)}</strong></div>${threshold&&!freeDelivery?`<small class="shipping-hint">${t('spendMore').replace('{amount}',money(remaining))}</small>`:''}`:''}<div class="checkout-total"><span>${t('total')}</span><span>${money(sub+shipping)}</span></div><button class="primary" onclick="requestQR()">${t('requestQR')}</button><p class="footer">${t('paymentHint')}</p>`}
function cart(){const rows=state.cart.map(i=>{const p=state.products.find(x=>x.id===i.id);if(!p)return '';return `<div class="cart-row"><div class="thumb">${image(p)}</div><div><p>${productName(p)}</p>${i.size?`<small>${t('sizes')}: ${i.size}</small>`:''}${i.color?`<small>${t('colors')}: ${colorName(i.color)}</small>`:''}<div class="quantity"><button onclick="change('${p.id}','${i.size||''}','${i.color||''}',-1)">−</button> ${i.qty} <button onclick="change('${p.id}','${i.size||''}','${i.color||''}',1)">+</button></div></div><div class="right"><b>${money(p.price*i.qty)}</b><br><button class="back" onclick="removeItem('${p.id}','${i.size||''}','${i.color||''}')">×</button></div></div>`}).join(''),sub=state.cart.reduce((n,i)=>n+(state.products.find(p=>p.id===i.id)?.price||0)*i.qty,0);return `<section class="panel"><button class="back home-return" onclick="showShop()">${t('backToHome')}</button><h2>${t('yourOrder')}</h2>${rows||`<div class="empty">${t('empty')}</div>`}${state.cart.length?checkout(sub):''}</section>`}
function shop(){const list=state.category==='all'?state.products:state.products.filter(p=>p.category===state.category),hero=state.language==='km'?state.settings.hero_km:state.settings.hero_en,heroText=state.language==='km'?state.settings.hero_text_km:state.settings.hero_text_en,promo=freeShippingMessage();return `<section class="hero"><div class="hero-main"><div class="eyebrow">${t('heroTag')}</div><h1>${hero}</h1><p>${heroText}</p></div><div class="hero-side"><strong>${t('new')}</strong></div></section>${customerActions()}<div class="section-head"><h2>${t('featured')}</h2><small>${list.length} ${t('items')}</small></div><div class="filters">${['all','clothes','bags','charms'].map(x=>`<button class="filter ${state.category===x?'selected':''}" onclick="setCategory('${x}')">${t(x)}</button>`).join('')}</div><div class="products">${list.length?list.map(p=>`<article class="product product-simple"><button class="product-image product-image-button" onclick="showProduct('${p.id}')">${image(p)}</button><div class="product-body"><h3 class="product-title"><button class="title-button" onclick="showProduct('${p.id}')">${productName(p)}</button></h3><div class="product-price">${money(p.price)}</div>${promo?`<p class="product-promo">${promo}</p>`:''}</div></article>`).join(''):`<div class="empty">${t('noProducts')}</div>`}</div><button class="cart" onclick="showCart()">${t('bag')} · ${state.cart.reduce((n,x)=>n+x.qty,0)}</button>`}
function settingsAdmin(){const fees=Object.entries(state.settings.shipping||{}).map(([k,v])=>`<div class="settings-row"><span>${k}</span><label>$ <input name="fee-${k}" value="${String(v).replace('$','')}"></label></div>`).join('');return `<div class="panel"><h2>${t('homeTitle')}</h2><form id="settings-form" onsubmit="saveSettings(event)"><label class="field">English headline<input name="hero_en" value="${state.settings.hero_en||''}"></label><label class="field">Khmer headline<input name="hero_km" value="${state.settings.hero_km||''}"></label><label class="field">English introduction<textarea name="hero_text_en">${state.settings.hero_text_en||''}</textarea></label><label class="field">Khmer introduction<textarea name="hero_text_km">${state.settings.hero_text_km||''}</textarea></label><label class="field">${t('pickupAddress')}<input name="pickup" value="${state.settings.pickup||''}"></label><h3>${t('shippingFees')}</h3>${fees}<label class="field">${t('freeShippingThreshold')}<input name="free_shipping_threshold" type="number" min="0" step="0.01" value="${shippingThreshold()||''}"><small>Enter 0 to turn off free delivery.</small></label><button class="primary">${t('save')}</button></form></div><div class="panel"><h2>${t('proofAlerts')}</h2><p class="description">${t('proofAlertsHint')}</p><button type="button" class="primary" onclick="connectTelegramOwner()">${t('connectTelegram')}</button></div>`}
async function saveSettings(event){event.preventDefault();const form=event.currentTarget,data=Object.fromEntries(new FormData(form));data.shipping={};Object.keys(state.settings.shipping||{}).forEach(k=>{data.shipping[k]='$'+Number(data[`fee-${k}`]||0).toFixed(2);delete data[`fee-${k}`]});data.free_shipping_threshold=Math.max(0,Number(data.free_shipping_threshold||0));try{await adminFetch('/api/admin/settings',{method:'PUT',body:JSON.stringify(data)});state.settings={...state.settings,...data};render();showAdminSuccess(t('saved'))}catch(error){if(error.message!=='Cancelled')alert(error.message)}}
async function requestQR(){const name=$('#customer-name')?.value.trim(),contact=$('#customer-contact')?.value.trim(),address=$('#customer-address')?.value.trim();if(!name||!contact||(state.delivery==='delivery'&&!address)){alert('Please complete the order details. / សូមបំពេញព័ត៌មានបញ្ជាទិញ។');return}const items=state.cart.map(i=>{const p=state.products.find(p=>p.id===i.id);return {name:p.name_en,size:i.size||'',color:i.color||'',quantity:i.qty,price:p.price}}),subtotal=items.reduce((n,i)=>n+i.quantity*i.price,0),shipping=shippingFor(subtotal);try{const response=await fetch('/api/orders',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({telegramInitData:window.Telegram?.WebApp?.initData||'',name,contact,address,delivery:state.delivery,region:state.region,items,subtotal,shipping,total:subtotal+shipping})});if(!response.ok)throw Error();state.cart=[];save();alert(t('orderSent'));showShop()}catch{alert(t('serverError'))}}
function myOrdersPage(){const orders=Array.isArray(state.myOrders)?state.myOrders:[];if(state.myOrdersLoading)return `<section class="panel"><button class="back home-return" onclick="showShop()">${t('backToHome')}</button><h2>${t('orderHistory')}</h2><div class="empty">Loading…</div></section>`;if(state.myOrdersError)return `<section class="panel"><button class="back home-return" onclick="showShop()">${t('backToHome')}</button><h2>${t('orderHistory')}</h2><div class="empty">${state.myOrdersError}</div></section>`;return `<section class="panel customer-orders"><button class="back home-return" onclick="showShop()">${t('backToHome')}</button><h2>${t('orderHistory')}</h2>${orders.length?orders.map(order=>{const items=Array.isArray(order.items)?order.items:[];return `<article class="customer-order"><div><b>${order.order_number}</b><br><small>${new Date(order.created_at).toLocaleString()}</small></div><span class="order-status status-${order.status}">${t(`status_${order.status}`)}</span><div class="customer-order-items">${items.map(item=>`<div>${item.quantity} × ${item.name}${item.size?` · ${item.size}`:''}${item.color?` · ${colorName(item.color)}`:''}</div>`).join('')}</div><strong>${money(order.total)}</strong><button class="danger customer-order-delete" onclick="deleteMyOrder('${order.id}')">${t('delete')}</button></article>`}).join(''):`<div class="empty">${t('noOrders')}</div>`}</section>`}
