function shippingBadge(){const threshold=shippingThreshold();return threshold?`<div class="shipping-badge"><b>${money(threshold)}</b><span>${t('freeShippingOver')}</span></div>`:''}
function shop(){const list=state.category==='all'?state.products:state.products.filter(p=>p.category===state.category),hero=state.language==='km'?state.settings.hero_km:state.settings.hero_en,heroText=state.language==='km'?state.settings.hero_text_km:state.settings.hero_text_en,badge=shippingBadge();return `<section class="hero"><div class="hero-main"><div class="eyebrow">${t('heroTag')}</div><h1>${hero}</h1><p>${heroText}</p></div><div class="hero-side"><strong>${t('new')}</strong></div></section>${customerActions()}<div class="section-head"><h2>${t('featured')}</h2><small>${list.length} ${t('items')}</small></div><div class="filters">${['all','clothes','bags','charms'].map(x=>`<button class="filter ${state.category===x?'selected':''}" onclick="setCategory('${x}')">${t(x)}</button>`).join('')}</div><div class="products product-showcase-list">${list.length?list.map(p=>`<article class="product product-showcase"><button class="product-image product-image-button" onclick="showProduct('${p.id}')">${image(p)}</button><div class="showcase-info"><h3 class="showcase-name"><button class="title-button" onclick="showProduct('${p.id}')">${productName(p)}</button></h3><div class="showcase-footer">${badge}<div class="showcase-price">${money(p.price)}</div></div></div></article>`).join(''):`<div class="empty">${t('noProducts')}</div>`}</div><button class="cart" onclick="showCart()">${t('bag')} · ${state.cart.reduce((n,x)=>n+x.qty,0)}</button>`}
