copy.en.followChannel='Follow our channel';copy.km.followChannel='តាមដានឆានែលរបស់យើង';
function openChannel(){const url='https://t.me/cypress1111';if(window.Telegram?.WebApp?.openTelegramLink)window.Telegram.WebApp.openTelegramLink(url);else window.open(url,'_blank','noopener')}
function channelButton(){return `<button class="channel-button" onclick="openChannel()">✈ ${t('followChannel')}</button>`}
function stockKey(size='',color=''){return [color&&`color:${color}`,size&&`size:${size}`].filter(Boolean).join('|')||'default'}
function stockFor(p,size='',color=''){return p.sale_type==='in_stock'?Math.max(0,Number(p.stock_by_sku?.[stockKey(size,color)]||0)):Infinity}
function productVariants(p){const sizes=p.category==='clothes'&&p.sizes?.length?p.sizes:[''],colors=p.colors?.length?p.colors:[''];return sizes.flatMap(size=>colors.map(color=>({size,color,key:stockKey(size,color)})))}
function soldOut(p){return p.sale_type==='in_stock'&&productVariants(p).every(v=>stockFor(p,v.size,v.color)<1)}
function saleBadge(p){return `<span class="sale-badge ${p.sale_type==='in_stock'?'stock':'preorder'}">${p.sale_type==='in_stock'?'IN STOCK / 现货':'PRE-ORDER / 预售'}</span>`}
function deliveryPromise(p,delivery='delivery'){return p?.sale_type==='preorder'?'预计15–18天到货':delivery==='pickup'?'下单后第二天可以取货':'预计3–4天送达'}
function chooseOption(id,type,value){const p=state.products.find(x=>x.id===id),other=selectedOption(id,type==='size'?'color':'size'),stock=type==='size'?stockFor(p,value,other):stockFor(p,other,value);if(stock<1){alert('SOLD OUT / 售罄');return}state.selectedVariants=state.selectedVariants||{};state.selectedVariants[variantKey(id,type)]=value;render()}
function inventoryVariantPicker(p){const sizes=p.category==='clothes'&&p.sizes?.length?p.sizes:[],colors=p.colors||[],size=selectedOption(p.id,'size'),color=selectedOption(p.id,'color'),guide=p.size_guides?.[size]||{},guideRows=[guide.recommendation&&`<span><b>${t('recommendedHeightWeight')}:</b> ${guide.recommendation}</span>`,guide.waist&&`<span><b>${t('waist')}:</b> ${guide.waist}</span>`,guide.length&&`<span><b>${t('pantsLength')}:</b> ${guide.length}</span>`].filter(Boolean).join(''),availability=(size||color||(!sizes.length&&!colors.length))&&p.sale_type==='in_stock'?`<small class="stock-left">${stockFor(p,size,color)>0?`${stockFor(p,size,color)} 件现货`:'SOLD OUT / 售罄'}</small>`:'';return `${sizes.length?`<div class="variant-group"><b>${t('sizes')}</b><div class="variant-options">${sizes.map(value=>{const disabled=colors.length?colors.every(c=>stockFor(p,value,c)<1):stockFor(p,value,'')<1;return `<button type="button" class="variant-chip ${size===value?'selected':''} ${disabled?'unavailable':''}" ${disabled?'disabled':''} onclick="chooseOption('${p.id}','size','${value}')">${value}</button>`}).join('')}</div>${guideRows?`<div class="customer-size-guide">${guideRows}</div>`:''}</div>`:''}${colors.length?`<div class="variant-group"><b>${t('colors')}</b><div class="variant-options">${colors.map(value=>{const option=colorOption(value),photo=p.color_images?.[option.value],name=colorName(value),disabled=sizes.length?(size?stockFor(p,size,option.value)<1:sizes.every(s=>stockFor(p,s,option.value)<1)):stockFor(p,'',option.value)<1;return `<button type="button" class="variant-chip color-chip ${color===option.value?'selected':''} ${disabled?'unavailable':''}" ${disabled?'disabled':''} onclick="chooseOption('${p.id}','color','${option.value}')">${photo?`<img class="variant-color-photo" src="${photo}" alt="${name}" onclick="event.stopPropagation();showColorPreview('${photo}','${name}')">`:`<span class="swatch" style="background:${option.tone}"></span>`}<span>${name}</span></button>`}).join('')}</div></div>`:''}${availability}`}
function add(id){const p=state.products.find(x=>x.id===id),sizes=p?.category==='clothes'&&p.sizes?.length?p.sizes:[],colors=p?.colors||[],size=selectedOption(id,'size'),color=selectedOption(id,'color');if(soldOut(p)){alert('SOLD OUT / 售罄');return}if(sizes.length&&!size){alert(t('chooseSize'));return}if(colors.length&&!color){alert(t('chooseColor'));return}if(stockFor(p,size,color)<1){alert('SOLD OUT / 售罄');return}const item=state.cart.find(x=>x.id===id&&(x.size||'')===size&&(x.color||'')===color);if(item&&item.qty>=stockFor(p,size,color)){alert('库存不足 / Not enough stock');return}item?item.qty++:state.cart.push({id,size,color,qty:1});save();render();showAddedMessage()}
function change(id,size,color,n){const item=state.cart.find(x=>x.id===id&&(x.size||'')===size&&(x.color||'')===color),p=state.products.find(x=>x.id===id);if(!item)return;if(n>0&&item.qty>=stockFor(p,size,color)){alert('库存不足 / Not enough stock');return}item.qty+=n;if(item.qty<1)state.cart=state.cart.filter(x=>x!==item);save();render()}
function productDetail(){const p=state.products.find(x=>x.id===state.productId);if(!p){showShop();return ''}const detail=p.detail_image_url||p.image_url,note=p.category==='bags'&&p.excludes_charms?`<p class="bag-charms-note">${t('excludesCharms')}</p>`:'',blocked=soldOut(p);return `<section class="panel product-detail"><button class="back" onclick="showShop()">${t('backToShop')}</button><div class="detail-info">${saleBadge(p)}<span class="category-label">${t(p.category)}</span><h2>${productName(p)}</h2><div class="detail-price">${money(p.price)}</div><p class="delivery-promise">${deliveryPromise(p)}</p>${note}<p class="detail-description">${description(p)}</p>${variantPicker(p)}<button class="add" ${blocked?'disabled':''} onclick="add('${p.id}')">${blocked?'SOLD OUT / 售罄':t('add')}</button></div><div class="long-detail-image"><img src="${detail}" alt="${p.name_en}"></div></section>`}
function shop(){const list=(state.category==='all'?state.products:state.products.filter(p=>p.category===state.category)),hero=state.language==='km'?state.settings.hero_km:state.settings.hero_en,heroText=state.language==='km'?state.settings.hero_text_km:state.settings.hero_text_en;return `<section class="hero"><div class="hero-main"><div class="eyebrow">${t('heroTag')}</div><h1>${hero}</h1><p>${heroText}</p></div><div class="hero-side"><strong>${t('new')}</strong></div></section>${customerActions()}${channelButton()}<div class="section-head"><h2>${t('featured')}</h2><small>${list.length} ${t('items')}</small></div><div class="filters">${['all','clothes','bags','charms'].map(x=>`<button class="filter ${state.category===x?'selected':''}" onclick="setCategory('${x}')">${t(x)}</button>`).join('')}</div><div class="products product-showcase-list">${list.length?list.map(p=>`<article class="product product-showcase ${soldOut(p)?'sold-out-card':''}"><button class="product-image product-image-button" onclick="showProduct('${p.id}')">${image(p)}${saleBadge(p)}${soldOut(p)?'<span class="sold-out-overlay">SOLD OUT<br>售罄</span>':''}</button><div class="showcase-info"><div class="showcase-footer"><h3 class="showcase-name"><button class="title-button" onclick="showProduct('${p.id}')">${productName(p)}</button></h3><div class="showcase-price">${money(p.price)}</div></div><small class="card-delivery">${deliveryPromise(p)}</small></div></article>`).join(''):`<div class="empty">${t('noProducts')}</div>`}</div><button class="cart" onclick="showCart()">${t('bag')} · ${state.cart.reduce((n,x)=>n+x.qty,0)}</button>`}
function formInventoryKeys(form,editing){const sizes=[...form.querySelectorAll('input[name="sizes"]:checked')].map(x=>x.value),colors=COLOR_OPTIONS.filter(c=>form.querySelector(`[data-color-image-field="${c.value}"]`)?.classList.contains('selected-color-upload')).map(c=>c.value),ss=sizes.length?sizes:[''],cc=colors.length?colors:[''];return ss.flatMap(size=>cc.map(color=>({size,color,key:stockKey(size,color)})))}
function inventoryFields(editing){const variants=productVariants(editing||{category:'bags',sizes:[],colors:[]});return `<div id="inventory-fields" class="inventory-editor">${variants.map(v=>`<label class="field" data-stock-row="${v.key}">${v.color?colorName(v.color):''}${v.color&&v.size?' / ':''}${v.size||'Default'} <input type="number" min="0" step="1" data-stock-sku="${v.key}" value="${editing?.stock_by_sku?.[v.key]??0}"></label>`).join('')}</div>`}
function refreshInventoryFields(){const form=$('#product-form'),box=$('#inventory-fields');if(!form||!box)return;const previous=Object.fromEntries([...box.querySelectorAll('[data-stock-sku]')].map(i=>[i.dataset.stockSku,i.value])),editing=state.editId?state.products.find(p=>p.id===state.editId):null,items=formInventoryKeys(form,editing);box.innerHTML=items.map(v=>`<label class="field" data-stock-row="${v.key}">${v.color?colorName(v.color):''}${v.color&&v.size?' / ':''}${v.size||'Default'} <input type="number" min="0" step="1" data-stock-sku="${v.key}" value="${previous[v.key]??editing?.stock_by_sku?.[v.key]??0}"></label>`).join('')}
function toggleSaleType(value){const field=$('#stock-editor-field');if(field)field.hidden=value!=='in_stock';if(value==='in_stock')refreshInventoryFields()}
function inventoryPreviewColorPhoto(input){const card=input.closest('.color-image-admin'),file=input.files?.[0];if(!card||!file)return;const preview=card.querySelector('img'),status=card.querySelector('.color-upload-status'),reader=new FileReader();reader.onload=()=>{preview.src=reader.result;preview.classList.remove('color-preview-empty');card.classList.add('selected-color-upload');status.textContent='Selected ✓';refreshInventoryFields()};reader.readAsDataURL(file)}
function productAdmin(){const e=state.editId?state.products.find(p=>p.id===state.editId):null,category=e?.category||'clothes',sizes=e?.sizes||[],images=e?.color_images||{},sale=e?.sale_type||'in_stock';return `<div class="admin-grid"><div class="panel"><h2>${e?t('editProduct'):t('upload')}</h2><form id="product-form" onsubmit="saveProduct(event)"><div class="form-grid"><label class="field">${t('productEn')}<input name="name_en" required value="${e?.name_en||''}"></label><label class="field">${t('productKm')}<input name="name_km" value="${e?.name_km||''}"></label></div><div class="form-grid"><label class="field">${t('price')}<input name="price" type="number" step="0.01" min="0" required value="${e?.price||''}"></label><label class="field">${t('category')}<select name="category" onchange="toggleSizeField(this.value);refreshInventoryFields()"><option value="clothes" ${category==='clothes'?'selected':''}>${t('clothes')}</option><option value="bags" ${category==='bags'?'selected':''}>${t('bags')}</option><option value="charms" ${category==='charms'?'selected':''}>${t('charms')}</option></select></label></div><label class="field">商品类型<select name="sale_type" onchange="toggleSaleType(this.value)"><option value="in_stock" ${sale==='in_stock'?'selected':''}>IN STOCK / 现货</option><option value="preorder" ${sale==='preorder'?'selected':''}>PRE-ORDER / 预售</option></select></label><div id="size-field" ${category==='clothes'?'':'hidden'}><label class="field">${t('chooseSizes')}</label>${sizeChoiceGrid(sizes)}<b class="admin-subhead">${t('sizeGuide')}</b>${sizeGuideFields(sizes,e?.size_guides||{})}</div><label id="bag-charms-field" class="admin-choice bag-charms-choice" ${category==='bags'?'':'hidden'}><input name="excludes_charms" type="checkbox" ${e?.excludes_charms?'checked':''}><span>${t('excludesCharmsAdmin')}</span></label><label class="field">${t('chooseColors')}</label>${colorImageFields([],images)}<div id="stock-editor-field" ${sale==='in_stock'?'':'hidden'}><b class="admin-subhead">现货库存（每个颜色 / 尺码）</b>${inventoryFields(e)}</div><label class="field">${t('descriptionEn')}<textarea name="description_en">${e?.description_en||''}</textarea></label><label class="field">${t('descriptionKm')}<textarea name="description_km">${e?.description_km||''}</textarea></label><label class="field">${t('mainPhoto')}<input name="main_photo" type="file" accept="image/png,image/jpeg,image/webp" ${e?'':'required'}></label><label class="field">${t('detailPhoto')}<input name="detail_photo" type="file" accept="image/png,image/jpeg,image/webp" ${e?'':'required'}></label><div class="checks"><label><input name="published" type="checkbox" ${e?.published===false?'':'checked'}> ${t('published')}</label><label><input name="featured" type="checkbox" ${e?.featured?'checked':''}> ${t('featuredItem')}</label></div><button class="primary">${e?t('update'):t('save')}</button>${e?`<button class="secondary" type="button" onclick="cancelEdit()">${t('cancel')}</button>`:''}</form></div><div class="panel"><h2>${t('products')}</h2><div class="admin-products">${state.products.map(p=>`<div class="admin-product"><div class="mini">${image(p)}</div><div><b>${p.name_en}</b><br><small>${p.sale_type==='in_stock'?'IN STOCK / 现货':'PRE-ORDER / 预售'} · ${money(p.price)}</small></div><button class="edit" onclick="beginEdit('${p.id}')">${t('edit')}</button><button class="danger" onclick="deleteProduct('${p.id}')">${t('delete')}</button></div>`).join('')}</div></div></div>`}
function inventoryAdmin(){const products=state.products.filter(p=>p.sale_type==='in_stock');return `<div class="panel"><h2>现货库存管理</h2>${products.length?products.map(p=>`<article class="inventory-product"><div class="mini">${image(p)}</div><div><b>${p.name_en}</b><br><small>IN STOCK / 现货</small></div></article><div class="inventory-list">${productVariants(p).map(v=>{const n=stockFor(p,v.size,v.color),sold=Number(p.sold_by_sku?.[v.key]||0),status=n===0?'Sold Out / 售罄':n<=3?'Low Stock / 库存不足':'In Stock / 有货';return `<div class="inventory-row"><span>${v.color?colorName(v.color):''}${v.color&&v.size?' / ':''}${v.size||'Default'}</span><small>已售 ${sold}</small><b class="${n===0?'sold':n<=3?'low':''}">${status}</b><input type="number" min="0" value="${n}" onchange="saveInventory('${p.id}','${v.key}',this.value)"></div>`}).join('')}</div>`).join(''):`<div class="empty">暂无现货商品。</div>`}</div>`}
async function saveInventory(id,key,value){const p=state.products.find(x=>x.id===id),stock={...(p?.stock_by_sku||{}),[key]:Math.max(0,Math.floor(Number(value)||0))};try{const saved=await adminFetch(`/api/admin/inventory/${id}`,{method:'PATCH',body:JSON.stringify({stock_by_sku:stock})});Object.assign(p,saved);showAdminSuccess('库存已保存 ✓');render()}catch(error){alert(error.message)}}
function admin(){return `<section><div class="section-head"><h2>${t('adminTitle')}</h2><button class="back admin-home" onclick="showShop()">${t('backToHome')}</button></div><label class="field"><b>${t('adminKey')}</b><input id="admin-key" type="password" placeholder="${t('adminKey')}"></label><div class="admin-nav">${[['products',t('products')],['inventory','现货库存'],['orders',t('orders')],['settings',t('settings')]].map(([x,label])=>`<button class="${state.adminTab===x?'selected':''}" onclick="adminTab('${x}')">${label}</button>`).join('')}</div>${state.adminTab==='products'?productAdmin():state.adminTab==='inventory'?inventoryAdmin():state.adminTab==='orders'?ordersAdmin():settingsAdmin()}</section>`}
async function saveProduct(event){event.preventDefault();const form=event.currentTarget,e=state.editId?state.products.find(p=>p.id===state.editId):null,main=form.main_photo.files[0],detail=form.detail_photo.files[0];if(!e&&(!main||!detail)){alert('Choose both photos.');return}const input=Object.fromEntries(new FormData(form));input.sizes=[...form.querySelectorAll('input[name="sizes"]:checked')].map(x=>x.value);input.size_guides={};form.querySelectorAll('[data-guide-size]').forEach(x=>{const s=x.dataset.guideSize;(input.size_guides[s]??={})[x.dataset.guideField]=x.value.trim()});input.color_images=e?.color_images||{};input.colorImageData={};await Promise.all([...form.querySelectorAll('[data-color-photo]')].map(async x=>{if(x.files[0])input.colorImageData[x.dataset.colorPhoto]=await toData(x.files[0])}));input.colors=COLOR_OPTIONS.filter(c=>input.color_images[c.value]||input.colorImageData[c.value]).map(c=>c.value);input.stock_by_sku=Object.fromEntries([...form.querySelectorAll('[data-stock-sku]')].map(x=>[x.dataset.stockSku,Math.max(0,Math.floor(Number(x.value)||0))]));input.excludes_charms=Boolean(form.excludes_charms?.checked);input.mainImageData=main?await toData(main):'';input.detailImageData=detail?await toData(detail):'';input.published=form.published.checked;input.featured=form.featured.checked;if(e){input.image_url=e.image_url;input.detail_image_url=e.detail_image_url||''}try{await adminFetch(e?`/api/admin/products/${e.id}`:'/api/admin/products',{method:e?'PATCH':'POST',body:JSON.stringify(input)});state.editId=null;await loadAdmin();render();showAdminSuccess('商品和库存已保存 ✓')}catch(error){alert(error.message)}}
async function requestQR(){const name=$('#customer-name')?.value.trim(),contact=$('#customer-contact')?.value.trim(),address=$('#customer-address')?.value.trim();if(!name||!contact||(state.delivery==='delivery'&&!address)){alert('Please complete the order details.');return}const items=state.cart.map(i=>{const p=state.products.find(x=>x.id===i.id);return {id:p.id,size:i.size||'',color:i.color||'',quantity:i.qty}});try{const response=await fetch('/api/orders',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({telegramInitData:window.Telegram?.WebApp?.initData||'',name,contact,address,delivery:state.delivery,region:state.region,items})}),result=await response.json();if(!response.ok)throw Error(result.error||'Could not create order.');state.cart=[];save();alert(t('orderSent'));showShop()}catch(error){alert(error.message||t('serverError'))}}
copy.en.chooseColors='Upload color photos (an uploaded photo means this color is available)';copy.km.chooseColors='ផ្ទុករូបភាពពណ៌ (មានរូបភាព មានន័យថាពណ៌នេះមាន)';
copy.en.colorPhotosSaved='Color photos saved ✓';copy.km.colorPhotosSaved='បានរក្សាទុករូបភាពពណ៌ ✓';
colorChoiceGrid=()=>'';
refreshVariantAdminFields=function(){const form=$('#product-form');if(!form)return;const sizes=new Set([...form.querySelectorAll('input[name="sizes"]:checked')].map(x=>x.value));form.querySelectorAll('[data-size-guide]').forEach(field=>field.hidden=!sizes.has(field.dataset.sizeGuide))};
colorImageFields=function(_selected,images){return `<div id="color-image-fields" class="admin-variant-fields color-upload-list">${COLOR_OPTIONS.map(color=>`<label class="color-image-admin ${images?.[color.value]?'selected-color-upload':''}" data-color-image-field="${color.value}"><span class="swatch" style="background:${color.tone}"></span><span>${color.en} / ${color.km}</span>${images?.[color.value]?`<img src="${images[color.value]}" alt="${color.en}">`:`<img class="color-preview-empty" alt="">`}<input type="file" accept="image/png,image/jpeg,image/webp" data-color-photo="${color.value}" onchange="previewColorPhoto(this)"><small class="color-upload-status">${images?.[color.value]?'Selected ✓':t('colorPhoto')}</small></label>`).join('')}</div>`}
function previewColorPhoto(input){const card=input.closest('.color-image-admin'),file=input.files?.[0];if(!card||!file)return;const preview=card.querySelector('img'),status=card.querySelector('.color-upload-status'),reader=new FileReader();reader.onload=()=>{preview.src=reader.result;preview.classList.remove('color-preview-empty');card.classList.add('selected-color-upload');status.textContent='Selected ✓'};reader.readAsDataURL(file)}
function showColorPreview(src,name){document.querySelector('.color-preview-modal')?.remove();const modal=document.createElement('div');modal.className='color-preview-modal';modal.innerHTML=`<div class="color-preview-dialog"><button type="button" onclick="this.closest('.color-preview-modal').remove()">×</button><img src="${src}" alt="${name}"><b>${name}</b></div>`;modal.onclick=event=>{if(event.target===modal)modal.remove()};document.body.append(modal)}
variantPicker=function(p){const sizes=p.category==='clothes'&&Array.isArray(p.sizes)?p.sizes:[],colors=Array.isArray(p.colors)?p.colors:[],size=selectedOption(p.id,'size'),color=selectedOption(p.id,'color'),guide=p.size_guides?.[size]||{},guideRows=[guide.recommendation?`<span><b>${t('recommendedHeightWeight')}:</b> ${guide.recommendation}</span>`:'',guide.waist?`<span><b>${t('waist')}:</b> ${guide.waist}</span>`:'',guide.length?`<span><b>${t('pantsLength')}:</b> ${guide.length}</span>`:''].filter(Boolean).join('');return `${sizes.length?`<div class="variant-group"><b>${t('sizes')}</b><div class="variant-options">${sizes.map(value=>`<button type="button" class="variant-chip ${size===value?'selected':''}" onclick="chooseOption('${p.id}','size','${value}')">${value}</button>`).join('')}</div>${guideRows?`<div class="customer-size-guide">${guideRows}</div>`:''}</div>`:''}${colors.length?`<div class="variant-group"><b>${t('colors')}</b><div class="variant-options">${colors.map(value=>{const option=colorOption(value),photo=p.color_images?.[option.value],name=colorName(value);return `<button type="button" class="variant-chip color-chip ${color===option.value?'selected':''}" onclick="chooseOption('${p.id}','color','${option.value}')">${photo?`<img class="variant-color-photo" src="${photo}" alt="${name}" onclick="event.stopPropagation();chooseOption('${p.id}','color','${option.value}');showColorPreview('${photo}','${name}')">`:`<span class="swatch" style="background:${option.tone}"></span>`}<span>${name}</span></button>`}).join('')}</div></div>`:''}`}
saveProduct=async function(event){event.preventDefault();const form=event.currentTarget,editing=state.editId?state.products.find(p=>p.id===state.editId):null,main=form.main_photo.files[0],detail=form.detail_photo.files[0];if(!editing&&(!main||!detail)){alert('Choose both a main photo and a detail photo.');return}const input=Object.fromEntries(new FormData(form));input.sizes=[...form.querySelectorAll('input[name="sizes"]:checked')].map(x=>x.value);input.size_guides={};form.querySelectorAll('[data-guide-size]').forEach(field=>{const size=field.dataset.guideSize;if(!input.size_guides[size])input.size_guides[size]={};input.size_guides[size][field.dataset.guideField]=field.value.trim()});input.color_images=editing?.color_images||{};input.colorImageData={};await Promise.all([...form.querySelectorAll('[data-color-photo]')].map(async field=>{if(field.files[0])input.colorImageData[field.dataset.colorPhoto]=await toData(field.files[0])}));input.colors=COLOR_OPTIONS.filter(color=>input.color_images[color.value]||input.colorImageData[color.value]).map(color=>color.value);input.excludes_charms=Boolean(form.excludes_charms?.checked);input.mainImageData=main?await toData(main):'';input.detailImageData=detail?await toData(detail):'';input.published=form.published.checked;input.featured=form.featured.checked;if(editing){input.image_url=editing.image_url;input.detail_image_url=editing.detail_image_url||''}try{await adminFetch(editing?`/api/admin/products/${editing.id}`:'/api/admin/products',{method:editing?'PATCH':'POST',body:JSON.stringify(input)});state.editId=null;await loadAdmin();render();showAdminSuccess(Object.keys(input.colorImageData).length?t('colorPhotosSaved'):(editing?t('saved'):t('productAdded')))}catch(error){if(error.message!=='Cancelled')alert(error.message)}}
function stockShop(){const list=state.category==='all'?state.products:state.products.filter(p=>p.category===state.category),hero=state.language==='km'?state.settings.hero_km:state.settings.hero_en,heroText=state.language==='km'?state.settings.hero_text_km:state.settings.hero_text_en;return `<section class="hero"><div class="hero-main"><div class="eyebrow">${t('heroTag')}</div><h1>${hero}</h1><p>${heroText}</p></div><div class="hero-side"><strong>${t('new')}</strong></div></section>${customerActions()}${channelButton()}<div class="section-head"><h2>${t('featured')}</h2><small>${list.length} ${t('items')}</small></div><div class="filters">${['all','clothes','bags','charms'].map(x=>`<button class="filter ${state.category===x?'selected':''}" onclick="setCategory('${x}')">${t(x)}</button>`).join('')}</div><div class="products product-showcase-list">${list.map(p=>`<article class="product product-showcase ${soldOut(p)?'sold-out-card':''}"><button class="product-image product-image-button" onclick="showProduct('${p.id}')">${image(p)}${saleBadge(p)}${soldOut(p)?'<span class="sold-out-overlay">SOLD OUT<br>售罄</span>':''}</button><div class="showcase-info"><div class="showcase-footer"><h3 class="showcase-name"><button class="title-button" onclick="showProduct('${p.id}')">${productName(p)}</button></h3><div class="showcase-price">${money(p.price)}</div></div><small class="card-delivery">${deliveryPromise(p)}</small></div></article>`).join('')||`<div class="empty">${t('noProducts')}</div>`}</div><button class="cart" onclick="showCart()">${t('bag')} · ${state.cart.reduce((n,x)=>n+x.qty,0)}</button>`}
async function saveStockProduct(event){event.preventDefault();const form=event.currentTarget,e=state.editId?state.products.find(p=>p.id===state.editId):null,main=form.main_photo.files[0],detail=form.detail_photo.files[0];if(!e&&(!main||!detail)){alert('Choose both photos.');return}const input=Object.fromEntries(new FormData(form));input.sizes=[...form.querySelectorAll('input[name="sizes"]:checked')].map(x=>x.value);input.size_guides={};form.querySelectorAll('[data-guide-size]').forEach(x=>{const s=x.dataset.guideSize;(input.size_guides[s]??={})[x.dataset.guideField]=x.value.trim()});input.color_images=e?.color_images||{};input.colorImageData={};await Promise.all([...form.querySelectorAll('[data-color-photo]')].map(async x=>{if(x.files[0])input.colorImageData[x.dataset.colorPhoto]=await toData(x.files[0])}));input.colors=COLOR_OPTIONS.filter(c=>input.color_images[c.value]||input.colorImageData[c.value]).map(c=>c.value);input.stock_by_sku=Object.fromEntries([...form.querySelectorAll('[data-stock-sku]')].map(x=>[x.dataset.stockSku,Math.max(0,Math.floor(Number(x.value)||0))]));input.excludes_charms=Boolean(form.excludes_charms?.checked);input.mainImageData=main?await toData(main):'';input.detailImageData=detail?await toData(detail):'';input.published=form.published.checked;input.featured=form.featured.checked;if(e){input.image_url=e.image_url;input.detail_image_url=e.detail_image_url||''}try{await adminFetch(e?`/api/admin/products/${e.id}`:'/api/admin/products',{method:e?'PATCH':'POST',body:JSON.stringify(input)});state.editId=null;await loadAdmin();render();showAdminSuccess('商品和库存已保存 ✓')}catch(error){alert(error.message)}}
queueMicrotask(()=>{shop=stockShop;saveProduct=saveStockProduct;variantPicker=inventoryVariantPicker;previewColorPhoto=inventoryPreviewColorPhoto});
function variantType(p,size='',color=''){const exact=stockKey(size,color),colorOnly=stockKey('',color);return p?.variant_sale_types?.[exact]||p?.variant_sale_types?.[colorOnly]||p?.sale_type||'preorder'}
function variantPhoto(p,color=''){const src=color&&p?.color_images?.[color];return src?`<img src="${src}" alt="${productName(p)}">`:image(p)}
function variantSaleLabel(type){return state.language==='km'?(type==='in_stock'?'មានស្តុក':'កក់ទុកមុន'):(type==='in_stock'?'IN STOCK':'PRE-ORDER')}
function variantDeliveryText(type,delivery='delivery'){if(type==='preorder')return state.language==='km'?'រំពឹងថានឹងមកដល់ក្នុងរយៈពេល 15–18 ថ្ងៃ':'Expected arrival: 15–18 days';if(delivery==='pickup')return state.language==='km'?'អាចមកយកបាននៅថ្ងៃបន្ទាប់':'Pickup available the next day';return state.language==='km'?'រំពឹងថានឹងដឹកដល់ក្នុងរយៈពេល 3–4 ថ្ងៃ':'Expected delivery: 3–4 days'}
function variantStock(p,size='',color=''){return variantType(p,size,color)==='in_stock'?Math.max(0,Number(p?.stock_by_sku?.[stockKey(size,color)]||0)):Infinity}
function productHasInStock(p){return productVariants(p).some(v=>variantType(p,v.size,v.color)==='in_stock')}
function productSoldOut(p){const vs=productVariants(p);return vs.length>0&&vs.every(v=>variantType(p,v.size,v.color)==='in_stock'&&variantStock(p,v.size,v.color)<1)}
function productCardType(p){return productHasInStock(p)?'in_stock':'preorder'}
function variantSaleBadge(type){return `<span class="sale-badge ${type==='in_stock'?'stock':'preorder'}">${variantSaleLabel(type)}</span>`}
function stockAwarePicker(p){const sizes=p.category==='clothes'&&p.sizes?.length?p.sizes:[],colors=p.colors||[],size=selectedOption(p.id,'size'),color=selectedOption(p.id,'color'),currentType=variantType(p,size,color),guide=p.size_guides?.[size]||{},guideRows=[guide.recommendation&&`<span><b>${t('recommendedHeightWeight')}:</b> ${guide.recommendation}</span>`,guide.waist&&`<span><b>${t('waist')}:</b> ${guide.waist}</span>`,guide.length&&`<span><b>${t('pantsLength')}:</b> ${guide.length}</span>`].filter(Boolean).join(''),availability=(size||color||(!sizes.length&&!colors.length))&&currentType==='in_stock'?`<small class="stock-left">${variantStock(p,size,color)>0?`${variantStock(p,size,color)} in stock`:'SOLD OUT / អស់ស្តុក'}</small>`:'';return `${sizes.length?`<div class="variant-group"><b>${t('sizes')}</b><div class="variant-options">${sizes.map(value=>{const unavailable=colors.length?colors.every(c=>variantType(p,value,c)==='in_stock'&&variantStock(p,value,c)<1):variantType(p,value,'')==='in_stock'&&variantStock(p,value,'')<1;return `<button type="button" class="variant-chip ${size===value?'selected':''} ${unavailable?'unavailable':''}" ${unavailable?'disabled':''} onclick="chooseOption('${p.id}','size','${value}')">${value}</button>`}).join('')}</div>${guideRows?`<div class="customer-size-guide">${guideRows}</div>`:''}</div>`:''}${colors.length?`<div class="variant-group"><b>${t('colors')}</b><div class="variant-options">${colors.map(value=>{const photo=p.color_images?.[value],name=colorName(value),unavailable=sizes.length?(size?variantType(p,size,value)==='in_stock'&&variantStock(p,size,value)<1:sizes.every(s=>variantType(p,s,value)==='in_stock'&&variantStock(p,s,value)<1)):variantType(p,'',value)==='in_stock'&&variantStock(p,'',value)<1;return `<button type="button" class="variant-chip color-chip ${color===value?'selected':''} ${unavailable?'unavailable':''}" ${unavailable?'disabled':''} onclick="chooseOption('${p.id}','color','${value}')">${photo?`<img class="variant-color-photo" src="${photo}" alt="${name}" onclick="event.stopPropagation();showColorPreview('${photo}','${name}')">`:`<span class="swatch" style="background:${colorOption(value).tone}"></span>`}<span>${name}</span></button>`}).join('')}</div></div>`:''}${availability}`}
function stockAwareDetail(){const p=state.products.find(x=>x.id===state.productId);if(!p){showShop();return ''}const size=selectedOption(p.id,'size'),color=selectedOption(p.id,'color'),type=variantType(p,size,color),blocked=type==='in_stock'&&variantStock(p,size,color)<1,detail=p.detail_image_url||p.image_url,note=p.category==='bags'&&p.excludes_charms?`<p class="bag-charms-note">${t('excludesCharms')}</p>`:'';return `<section class="panel product-detail"><button class="back" onclick="showShop()">${t('backToShop')}</button><div class="detail-info">${variantSaleBadge(type)}<span class="category-label">${t(p.category)}</span><h2>${productName(p)}</h2><div class="detail-price">${money(p.price)}</div>${note}<p class="detail-description">${description(p)}</p>${stockAwarePicker(p)}<button class="add" ${blocked?'disabled':''} onclick="add('${p.id}')">${blocked?'SOLD OUT / អស់ស្តុក':t('add')}</button></div><div class="long-detail-image"><img src="${detail}" alt="${p.name_en}"></div></section>`}
function stockAwareAdd(id){const p=state.products.find(x=>x.id===id),sizes=p?.category==='clothes'&&p.sizes?.length?p.sizes:[],colors=p?.colors||[],size=selectedOption(id,'size'),color=selectedOption(id,'color'),type=variantType(p,size,color);if(sizes.length&&!size){alert(t('chooseSize'));return}if(colors.length&&!color){alert(t('chooseColor'));return}if(type==='in_stock'&&variantStock(p,size,color)<1){alert('SOLD OUT / អស់ស្តុក');return}const item=state.cart.find(x=>x.id===id&&(x.size||'')===size&&(x.color||'')===color);if(type==='in_stock'&&item&&item.qty>=variantStock(p,size,color)){alert('库存不足 / Not enough stock');return}item?item.qty++:state.cart.push({id,size,color,qty:1});save();render();showAddedMessage()}
function stockAwareChange(id,size,color,n){const item=state.cart.find(x=>x.id===id&&(x.size||'')===size&&(x.color||'')===color),p=state.products.find(x=>x.id===id);if(!item)return;if(n>0&&variantType(p,size,color)==='in_stock'&&item.qty>=variantStock(p,size,color)){alert('库存不足 / Not enough stock');return}item.qty+=n;if(item.qty<1)state.cart=state.cart.filter(x=>x!==item);save();render()}
function stockAwareCart(){const rows=state.cart.map(i=>{const p=state.products.find(x=>x.id===i.id);if(!p)return '';return `<div class="cart-row"><div class="thumb">${variantPhoto(p,i.color)}</div><div><p>${productName(p)}</p>${i.size?`<small>${t('sizes')}: ${i.size}</small>`:''}${i.color?`<small>${t('colors')}: ${colorName(i.color)}</small>`:''}<small>${variantSaleLabel(variantType(p,i.size,i.color))}</small><div class="quantity"><button onclick="change('${p.id}','${i.size||''}','${i.color||''}',-1)">−</button> ${i.qty} <button onclick="change('${p.id}','${i.size||''}','${i.color||''}',1)">+</button></div></div><div class="right"><b>${money(p.price*i.qty)}</b><br><button class="back" onclick="removeItem('${p.id}','${i.size||''}','${i.color||''}')">×</button></div></div>`}).join(''),sub=state.cart.reduce((n,i)=>n+(state.products.find(p=>p.id===i.id)?.price||0)*i.qty,0);return `<section class="panel"><button class="back" onclick="showShop()">${t('continue')}</button><h2>${t('yourOrder')}</h2>${rows||`<div class="empty">${t('empty')}</div>`}${state.cart.length?checkout(sub):''}</section>`}
function stockAwareShop(){const list=state.category==='all'?state.products:state.products.filter(p=>p.category===state.category),hero=state.language==='km'?state.settings.hero_km:state.settings.hero_en,heroText=state.language==='km'?state.settings.hero_text_km:state.settings.hero_text_en;return `<section class="hero"><div class="hero-main"><div class="eyebrow">${t('heroTag')}</div><h1>${hero}</h1><p>${heroText}</p></div><div class="hero-side"><strong>${t('new')}</strong></div></section>${customerActions()}${channelButton()}<div class="section-head"><h2>${t('featured')}</h2><small>${list.length} ${t('items')}</small></div><div class="filters">${['all','clothes','bags','charms'].map(x=>`<button class="filter ${state.category===x?'selected':''}" onclick="setCategory('${x}')">${t(x)}</button>`).join('')}</div><div class="products product-showcase-list">${list.map(p=>{const sold=productSoldOut(p),type=productCardType(p);return `<article class="product product-showcase ${sold?'sold-out-card':''}"><button class="product-image product-image-button" onclick="showProduct('${p.id}')">${image(p)}${sold?'<span class="sold-out-overlay">SOLD OUT<br>អស់ស្តុក</span>':''}</button><div class="showcase-info"><div class="showcase-footer"><h3 class="showcase-name"><button class="title-button" onclick="showProduct('${p.id}')">${productName(p)}</button></h3><div class="showcase-price">${money(p.price)}</div></div><div class="card-stock-line">${variantSaleBadge(type)}</div></div></article>`}).join('')||`<div class="empty">${t('noProducts')}</div>`}</div><button class="cart" onclick="showCart()">${t('bag')} · ${state.cart.reduce((n,x)=>n+x.qty,0)}</button>`}
function cleanCheckout(sub){const regions=Object.keys(state.settings.shipping||{});if(!regions.includes(state.region))state.region=regions[0]||'';const threshold=shippingThreshold(),freeDelivery=state.delivery==='delivery'&&threshold&&sub>=threshold,shipping=shippingFor(sub),remaining=Math.max(0,threshold-sub);return `<div class="form-grid"><label class="field">${t('name')}<input id="customer-name"></label><label class="field">${t('contact')}<input id="customer-contact" placeholder="@username or 012…"></label></div><div class="delivery"><button class="${state.delivery==='delivery'?'selected':''}" onclick="delivery('delivery')"><b>${t('delivery')}</b><br><small>${t('deliveryHint')}</small></button><button class="${state.delivery==='pickup'?'selected':''}" onclick="delivery('pickup')"><b>${t('pickup')}</b><br><small>${state.settings.pickup}</small></button></div>${state.delivery==='delivery'?`<label class="field">${t('region')}<select onchange="region(this.value)">${regions.map(k=>`<option ${k===state.region?'selected':''}>${k}</option>`).join('')}</select></label><label class="field">${t('address')}<textarea id="customer-address" placeholder="${t('addressHint')}"></textarea></label><div class="shipping-summary"><span>${t('shipping')}</span><strong>${freeDelivery?t('freeDelivery'):money(shipping)}</strong></div>${threshold&&!freeDelivery?`<small class="shipping-hint">${t('spendMore').replace('{amount}',money(remaining))}</small>`:''}`:`<div class="notice">${t('pickupNotice')} ${state.settings.pickup}</div>`}<div class="checkout-total"><span>${t('total')}</span><span>${money(sub+shipping)}</span></div><button class="primary" onclick="requestQR()">${t('requestQR')}</button><p class="footer">${t('paymentHint')}</p>`}
function colorVariantStocks(color,type,sizes,editing){if(type!=='in_stock')return `<div class="color-stock-fields" data-color-stock="${color}" hidden></div>`;const ss=sizes.length?sizes:[''];return `<div class="color-stock-fields" data-color-stock="${color}">${ss.map(size=>{const key=stockKey(size,color);return `<label>${size||'Default'} <input type="number" min="0" step="1" data-stock-sku="${key}" value="${editing?.stock_by_sku?.[key]??0}"> ${state.language==='km'?'ក្នុងស្តុក':'in stock'}</label>`}).join('')}</div>`}
function colorVariantFields(editing){const sizes=editing?.category==='clothes'?(editing.sizes||[]):[],images=editing?.color_images||{};return `<div id="color-image-fields" class="admin-variant-fields color-upload-list">${COLOR_OPTIONS.map(color=>{const current=images[color.value],type=editing?.variant_sale_types?.[stockKey(sizes[0]||'',color.value)]||editing?.variant_sale_types?.[stockKey('',color.value)]||editing?.sale_type||'preorder';return `<label class="color-image-admin ${current?'selected-color-upload':''}" data-color-image-field="${color.value}"><span class="swatch" style="background:${color.tone}"></span><span>${color.en} / ${color.km}</span>${current?`<img src="${current}" alt="${color.en}">`:`<img class="color-preview-empty" alt="">`}<input type="file" accept="image/png,image/jpeg,image/webp" data-color-photo="${color.value}" onchange="previewColorPhoto(this)"><small class="color-upload-status">${current?'Selected ✓':t('colorPhoto')}</small><span class="color-type-label">${state.language==='km'?'ប្រភេទលក់':'Sale type'}</span><select data-variant-type="${color.value}" onchange="refreshColorStockFields()"><option value="preorder" ${type==='preorder'?'selected':''}>PRE-ORDER / កក់ទុកមុន</option><option value="in_stock" ${type==='in_stock'?'selected':''}>IN STOCK / មានស្តុក</option></select>${colorVariantStocks(color.value,type,sizes,editing)}</label>`}).join('')}</div>`}
function refreshColorStockFields(){const form=$('#product-form');if(!form)return;const sizes=[...form.querySelectorAll('input[name="sizes"]:checked')].map(x=>x.value);form.querySelectorAll('[data-variant-type]').forEach(select=>{const color=select.dataset.variantType,card=select.closest('[data-color-image-field]'),box=card?.querySelector('[data-color-stock]');if(!box)return;const previous=Object.fromEntries([...box.querySelectorAll('[data-stock-sku]')].map(x=>[x.dataset.stockSku,x.value]));if(select.value!=='in_stock'){box.hidden=true;box.innerHTML='';return}box.hidden=false;box.innerHTML=(sizes.length?sizes:['']).map(size=>{const key=stockKey(size,color);return `<label>${size||'Default'} <input type="number" min="0" step="1" data-stock-sku="${key}" value="${previous[key]??0}"> ${state.language==='km'?'ក្នុងស្តុក':'in stock'}</label>`}).join('')})}
function variantAdminPhoto(input){const card=input.closest('.color-image-admin'),file=input.files?.[0];if(!card||!file)return;const preview=card.querySelector('img'),status=card.querySelector('.color-upload-status'),reader=new FileReader();reader.onload=()=>{preview.src=reader.result;preview.classList.remove('color-preview-empty');card.classList.add('selected-color-upload');status.textContent='Selected ✓';refreshColorStockFields()};reader.readAsDataURL(file)}
function variantProductAdmin(){const e=state.editId?state.products.find(p=>p.id===state.editId):null,category=e?.category||'clothes',sizes=e?.sizes||[];return `<div class="admin-grid"><div class="panel"><h2>${e?t('editProduct'):t('upload')}</h2><form id="product-form" onsubmit="saveProduct(event)"><div class="form-grid"><label class="field">${t('productEn')}<input name="name_en" required value="${e?.name_en||''}"></label><label class="field">${t('productKm')}<input name="name_km" value="${e?.name_km||''}"></label></div><div class="form-grid"><label class="field">${t('price')}<input name="price" type="number" step="0.01" min="0" required value="${e?.price||''}"></label><label class="field">${t('category')}<select name="category" onchange="toggleSizeField(this.value);refreshColorStockFields()"><option value="clothes" ${category==='clothes'?'selected':''}>${t('clothes')}</option><option value="bags" ${category==='bags'?'selected':''}>${t('bags')}</option><option value="charms" ${category==='charms'?'selected':''}>${t('charms')}</option></select></label></div><div id="size-field" ${category==='clothes'?'':'hidden'}><label class="field">${t('chooseSizes')}</label>${sizeChoiceGrid(sizes)}<b class="admin-subhead">${t('sizeGuide')}</b>${sizeGuideFields(sizes,e?.size_guides||{})}</div><label id="bag-charms-field" class="admin-choice bag-charms-choice" ${category==='bags'?'':'hidden'}><input name="excludes_charms" type="checkbox" ${e?.excludes_charms?'checked':''}><span>${t('excludesCharmsAdmin')}</span></label><label class="field">${t('chooseColors')}<small>${state.language==='km'?'ផ្ទុករូបភាព រួចកំណត់ពណ៌នីមួយៗថាជា 现货 ឬ 预售':'Upload the color photo, then set each color as IN STOCK or PRE-ORDER.'}</small></label>${colorVariantFields(e)}<label class="field">${t('descriptionEn')}<textarea name="description_en">${e?.description_en||''}</textarea></label><label class="field">${t('descriptionKm')}<textarea name="description_km">${e?.description_km||''}</textarea></label><label class="field">${t('mainPhoto')}<input name="main_photo" type="file" accept="image/png,image/jpeg,image/webp" ${e?'':'required'}></label><label class="field">${t('detailPhoto')}<input name="detail_photo" type="file" accept="image/png,image/jpeg,image/webp" ${e?'':'required'}></label><div class="checks"><label><input name="published" type="checkbox" ${e?.published===false?'':'checked'}> ${t('published')}</label><label><input name="featured" type="checkbox" ${e?.featured?'checked':''}> ${t('featuredItem')}</label></div><button class="primary">${e?t('update'):t('save')}</button>${e?`<button class="secondary" type="button" onclick="cancelEdit()">${t('cancel')}</button>`:''}</form></div><div class="panel"><h2>${t('products')}</h2><div class="admin-products">${state.products.map(p=>`<div class="admin-product"><div class="mini">${image(p)}</div><div><b>${p.name_en}</b><br><small>${productHasInStock(p)?'IN STOCK / 有现货':'PRE-ORDER / 预售'} · ${money(p.price)}</small></div><button class="edit" onclick="beginEdit('${p.id}')">${t('edit')}</button><button class="danger" onclick="deleteProduct('${p.id}')">${t('delete')}</button></div>`).join('')}</div></div></div>`}
async function saveVariantProduct(event){event.preventDefault();const form=event.currentTarget,e=state.editId?state.products.find(p=>p.id===state.editId):null,main=form.main_photo.files[0],detail=form.detail_photo.files[0];if(!e&&(!main||!detail)){alert('Choose both photos.');return}const input=Object.fromEntries(new FormData(form));input.sizes=[...form.querySelectorAll('input[name="sizes"]:checked')].map(x=>x.value);input.size_guides={};form.querySelectorAll('[data-guide-size]').forEach(x=>{const s=x.dataset.guideSize;(input.size_guides[s]??={})[x.dataset.guideField]=x.value.trim()});input.color_images=e?.color_images||{};input.colorImageData={};await Promise.all([...form.querySelectorAll('[data-color-photo]')].map(async x=>{if(x.files[0])input.colorImageData[x.dataset.colorPhoto]=await toData(x.files[0])}));input.colors=COLOR_OPTIONS.filter(c=>input.color_images[c.value]||input.colorImageData[c.value]).map(c=>c.value);input.variant_sale_types={};input.stock_by_sku=Object.fromEntries([...form.querySelectorAll('[data-stock-sku]')].map(x=>[x.dataset.stockSku,Math.max(0,Math.floor(Number(x.value)||0))]));const selectedSizes=input.sizes.length?input.sizes:[''];form.querySelectorAll('[data-variant-type]').forEach(select=>{const color=select.dataset.variantType;if(!input.colors.includes(color))return;selectedSizes.forEach(size=>input.variant_sale_types[stockKey(size,color)]=select.value)});if(!input.colors.length){input.variant_sale_types.default='preorder'}input.sale_type=Object.values(input.variant_sale_types).includes('in_stock')?'in_stock':'preorder';input.excludes_charms=Boolean(form.excludes_charms?.checked);input.mainImageData=main?await toData(main):'';input.detailImageData=detail?await toData(detail):'';input.published=form.published.checked;input.featured=form.featured.checked;if(e){input.image_url=e.image_url;input.detail_image_url=e.detail_image_url||''}try{await adminFetch(e?`/api/admin/products/${e.id}`:'/api/admin/products',{method:e?'PATCH':'POST',body:JSON.stringify(input)});state.editId=null;await loadAdmin();render();showAdminSuccess('商品、颜色和库存已保存 ✓')}catch(error){alert(error.message)}}
function variantInventoryAdmin(){const products=state.products.filter(productHasInStock);return `<div class="panel"><h2>现货库存管理</h2>${products.length?products.map(p=>`<article class="inventory-product"><div class="mini">${image(p)}</div><div><b>${p.name_en}</b><br><small>IN STOCK / 现货</small></div></article><div class="inventory-list">${productVariants(p).filter(v=>variantType(p,v.size,v.color)==='in_stock').map(v=>{const n=variantStock(p,v.size,v.color),sold=Number(p.sold_by_sku?.[v.key]||0),status=n===0?'Sold Out / 售罄':n<=3?'Low Stock / 库存不足':'In Stock / 有货';return `<div class="inventory-row"><span>${v.color?colorName(v.color):''}${v.color&&v.size?' / ':''}${v.size||'Default'}</span><small>已售 ${sold}</small><b class="${n===0?'sold':n<=3?'low':''}">${status}</b><input type="number" min="0" value="${n}" onchange="saveInventory('${p.id}','${v.key}',this.value)"></div>`}).join('')}</div>`).join(''):`<div class="empty">暂无现货商品。</div>`}</div>`}
document.addEventListener('change',event=>{if(event.target?.name==='sizes')setTimeout(refreshColorStockFields,0)});
function alignedShop(){const list=state.category==='all'?state.products:state.products.filter(p=>p.category===state.category),hero=state.language==='km'?state.settings.hero_km:state.settings.hero_en,heroText=state.language==='km'?state.settings.hero_text_km:state.settings.hero_text_en;return `<section class="hero"><div class="hero-main"><div class="eyebrow">${t('heroTag')}</div><h1>${hero}</h1><p>${heroText}</p></div><div class="hero-side"><strong>${t('new')}</strong></div></section>${customerActions()}${channelButton()}<div class="section-head"><h2>${t('featured')}</h2><small>${list.length} ${t('items')}</small></div><div class="filters">${['all','clothes','bags','charms'].map(x=>`<button class="filter ${state.category===x?'selected':''}" onclick="setCategory('${x}')">${t(x)}</button>`).join('')}</div><div class="products product-showcase-list">${list.map(p=>{const sold=productSoldOut(p),type=productCardType(p),name=productName(p);return `<article class="product product-showcase ${sold?'sold-out-card':''}"><button class="product-image product-image-button" onclick="showProduct('${p.id}')">${image(p)}${sold?'<span class="sold-out-overlay">SOLD OUT<br>អស់ស្តុក</span>':''}</button><div class="showcase-info showcase-info-aligned"><h3 class="showcase-name ${name.length>20?'two-lines':''}"><button class="title-button" onclick="showProduct('${p.id}')">${name}</button></h3><div class="showcase-bottom">${variantSaleBadge(type)}<div class="showcase-price">${money(p.price)}</div></div></div></article>`}).join('')||`<div class="empty">${t('noProducts')}</div>`}</div><button class="cart" onclick="showCart()">${t('bag')} · ${state.cart.reduce((n,x)=>n+x.qty,0)}</button>`}
function validSale(order){return ['paid','shipping','ready_for_pickup','completed'].includes(order.status)}
function productSales(product){const rows=[];state.orders.forEach(order=>{if(!validSale(order))return;(order.items||[]).forEach(item=>{if(item.id===product.id||(!item.id&&item.name===product.name_en))rows.push({order,item})})});const qty=rows.reduce((n,x)=>n+Number(x.item.quantity||0),0),stock=rows.filter(x=>x.item.sale_type==='in_stock').reduce((n,x)=>n+Number(x.item.quantity||0),0),preorder=qty-stock,revenue=rows.reduce((n,x)=>n+Number(x.item.price||0)*Number(x.item.quantity||0),0),latest=rows.sort((a,b)=>new Date(b.order.created_at)-new Date(a.order.created_at))[0]?.order.created_at;return {rows,qty,stock,preorder,revenue,latest}}
function manageStock(product){return productHasInStock(product)?productVariants(product).filter(v=>variantType(product,v.size,v.color)==='in_stock').reduce((n,v)=>n+variantStock(product,v.size,v.color),0):null}
function manageFilter(value){state.manageFilter=value;render()}function manageSearch(value){state.manageSearch=value;render()}function manageSort(value){state.manageSort=value;render()}
async function togglePublished(id,published){try{const saved=await adminFetch(`/api/admin/products/${id}/publish`,{method:'PATCH',body:JSON.stringify({published})});const p=state.products.find(x=>x.id===id);Object.assign(p,saved);render()}catch(error){alert(error.message)}}
function openSales(id){state.manageSalesId=id;render()}function closeSales(){state.manageSalesId=null;render()}
function productManagement(){const current=state.products.find(p=>p.id===state.manageSalesId);if(current){const m=productSales(current);return `<div class="panel"><button class="back" onclick="closeSales()">← 返回商品管理</button><h2>${current.name_en} · 销售详情</h2><div class="sales-summary"><span>累计售出 <b>${m.qty}</b></span><span>现货 <b>${m.stock}</b></span><span>预售 <b>${m.preorder}</b></span><span>销售额 <b>${money(m.revenue)}</b></span></div><div class="sales-records">${m.rows.map(({order,item})=>`<article><b>${order.order_number}</b><small>${new Date(order.created_at).toLocaleString()}</small><span>${order.customer_name} · ${item.quantity} 件 · ${item.color||'-'} / ${item.size||'-'}</span><span>${item.sale_type==='in_stock'?'现货':'预售'} · ${order.delivery==='pickup'?'自提':'快递'} · ${money(item.price)} · ${order.status}</span><strong>${money(Number(item.price||0)*Number(item.quantity||0))}</strong></article>`).join('')||'<div class="empty">暂无有效销售记录。</div>'}</div></div>`}const filter=state.manageFilter||'all',search=(state.manageSearch||'').toLowerCase(),sort=state.manageSort||'new';let products=state.products.filter(p=>{const sold=productSoldOut(p),inStock=productHasInStock(p),match=!search||p.name_en.toLowerCase().includes(search)||p.id.toLowerCase().includes(search);return match&&(filter==='all'||filter==='published'&&p.published||filter==='unpublished'&&!p.published||filter==='stock'&&inStock||filter==='preorder'&&!inStock||filter==='soldout'&&sold)});products.sort((a,b)=>{const x=productSales(a),y=productSales(b);return sort==='qty-desc'?y.qty-x.qty:sort==='qty-asc'?x.qty-y.qty:sort==='revenue'?y.revenue-x.revenue:new Date(b.created_at)-new Date(a.created_at)});const all=state.products.map(productSales),today=new Date().toDateString(),todayRows=all.flatMap(m=>m.rows).filter(x=>new Date(x.order.created_at).toDateString()===today),overview=[['商品总数',state.products.length],['已上架',state.products.filter(p=>p.published).length],['已下架',state.products.filter(p=>!p.published).length],['现货',state.products.filter(productHasInStock).length],['预售',state.products.filter(p=>!productHasInStock(p)).length],['今日售出',todayRows.reduce((n,x)=>n+Number(x.item.quantity||0),0)],['今日销售额',money(todayRows.reduce((n,x)=>n+Number(x.item.price||0)*Number(x.item.quantity||0),0))],['累计售出',all.reduce((n,x)=>n+x.qty,0)],['累计销售额',money(all.reduce((n,x)=>n+x.revenue,0))]];return `<section><div class="manage-overview">${overview.map(x=>`<div><small>${x[0]}</small><b>${x[1]}</b></div>`).join('')}</div><div class="manage-tools"><input placeholder="搜索商品名称 / SKU" value="${state.manageSearch||''}" oninput="manageSearch(this.value)"><select onchange="manageFilter(this.value)">${[['all','全部商品'],['published','已上架'],['unpublished','已下架'],['stock','现货'],['preorder','预售'],['soldout','售罄']].map(x=>`<option value="${x[0]}" ${filter===x[0]?'selected':''}>${x[1]}</option>`).join('')}</select><select onchange="manageSort(this.value)">${[['new','最新上架'],['qty-desc','销量从高到低'],['qty-asc','销量从低到高'],['revenue','销售金额从高到低']].map(x=>`<option value="${x[0]}" ${sort===x[0]?'selected':''}>${x[1]}</option>`).join('')}</select></div><div class="manage-products">${products.map(p=>{const m=productSales(p),stock=manageStock(p),sku=p.id.slice(0,8).toUpperCase();return `<article class="manage-product"><div class="mini">${image(p)}</div><div class="manage-main"><b>${p.name_en}</b><small>SKU: ${sku} · ${money(p.price)} · ${productHasInStock(p)?'现货':'预售'}</small><small>${stock===null?'无需库存':`现货库存：${stock}`} · ${p.published?'已上架':'已下架'}</small><small>已售 ${m.qty}（现货 ${m.stock} / 预售 ${m.preorder}）· 销售额 ${money(m.revenue)}${m.latest?` · 最近售出 ${new Date(m.latest).toLocaleDateString()}`:''}</small></div><div class="manage-actions"><button class="edit" onclick="state.editId='${p.id}';state.adminTab='products';render()">编辑</button><button onclick="openSales('${p.id}')">销售详情</button><button class="${p.published?'danger':'primary'}" onclick="togglePublished('${p.id}',${!p.published})">${p.published?'下架':'上架'}</button></div></article>`}).join('')||'<div class="empty">没有符合条件的商品。</div>'}</div></section>`}
function managementAdmin(){return `<section><div class="section-head"><h2>${t('adminTitle')}</h2><button class="back admin-home" onclick="showShop()">${t('backToHome')}</button></div><label class="field"><b>${t('adminKey')}</b><input id="admin-key" type="password" placeholder="${t('adminKey')}"></label><div class="admin-nav">${[['products','新增 / 编辑'],['inventory','商品管理'],['orders',t('orders')],['settings',t('settings')]].map(([x,label])=>`<button class="${state.adminTab===x?'selected':''}" onclick="adminTab('${x}')">${label}</button>`).join('')}</div>${state.adminTab==='products'?productAdmin():state.adminTab==='inventory'?productManagement():state.adminTab==='orders'?ordersAdmin():settingsAdmin()}</section>`}
function managedOrders(){return `<div class="panel"><h2>${t('orders')}</h2><table class="orders"><tr><th>${t('order')}</th><th>${t('customer')}</th><th>${t('total')}</th><th>${t('status')}</th></tr>${state.orders.map(o=>`<tr><td>${o.order_number}<br><small>${new Date(o.created_at).toLocaleDateString()}</small></td><td>${o.customer_name}<br><small>${o.contact}</small></td><td>${money(o.total)}</td><td><select onchange="setOrderStatus('${o.id}',this.value)">${['awaiting_payment','paid','shipping','ready_for_pickup','completed','cancelled'].map(s=>`<option value="${s}" ${s===o.status?'selected':''}>${s}</option>`).join('')}</select></td></tr>`).join('')||`<tr><td colspan="4">${t('empty')}</td></tr>`}</table></div>`}
queueMicrotask(()=>{admin=managementAdmin;inventoryAdmin=productManagement;ordersAdmin=managedOrders});
queueMicrotask(()=>{shop=alignedShop;cart=stockAwareCart;checkout=cleanCheckout;productDetail=stockAwareDetail;variantPicker=stockAwarePicker;add=stockAwareAdd;change=stockAwareChange;productAdmin=variantProductAdmin;saveProduct=saveVariantProduct;previewColorPhoto=variantAdminPhoto;admin=managementAdmin;inventoryAdmin=productManagement;ordersAdmin=managedOrders});
// The checkout promise follows the product type in the cart, so customers see the
// same delivery expectation before they submit an order.
function checkout(sub){const regions=Object.keys(state.settings.shipping||{});if(!regions.includes(state.region))state.region=regions[0]||'';const threshold=shippingThreshold(),freeDelivery=state.delivery==='delivery'&&threshold&&sub>=threshold,shipping=shippingFor(sub),remaining=Math.max(0,threshold-sub),promises=[...new Set(state.cart.map(item=>deliveryPromise(state.products.find(p=>p.id===item.id),state.delivery)))];return `<div class="form-grid"><label class="field">${t('name')}<input id="customer-name"></label><label class="field">${t('contact')}<input id="customer-contact" placeholder="@username or 012…"></label></div><div class="delivery"><button class="${state.delivery==='delivery'?'selected':''}" onclick="delivery('delivery')"><b>${t('delivery')}</b><br><small>${t('deliveryHint')}</small></button><button class="${state.delivery==='pickup'?'selected':''}" onclick="delivery('pickup')"><b>${t('pickup')}</b><br><small>${state.settings.pickup}</small></button></div><div class="delivery-promise checkout-promise">${promises.join(' · ')}</div>${state.delivery==='delivery'?`<label class="field">${t('region')}<select onchange="region(this.value)">${regions.map(k=>`<option ${k===state.region?'selected':''}>${k}</option>`).join('')}</select></label><label class="field">${t('address')}<textarea id="customer-address" placeholder="${t('addressHint')}"></textarea></label><div class="shipping-summary"><span>${t('shipping')}</span><strong>${freeDelivery?t('freeDelivery'):money(shipping)}</strong></div>${threshold&&!freeDelivery?`<small class="shipping-hint">${t('spendMore').replace('{amount}',money(remaining))}</small>`:''}`:`<div class="notice">${t('pickupNotice')} ${state.settings.pickup}</div>`}<div class="checkout-total"><span>${t('total')}</span><span>${money(sub+shipping)}</span></div><button class="primary" onclick="requestQR()">${t('requestQR')}</button><p class="footer">${t('paymentHint')}</p>`}
// Keep this save handler late: older revisions above define the same function.
async function saveProduct(event){event.preventDefault();const form=event.currentTarget,editing=state.editId?state.products.find(p=>p.id===state.editId):null,main=form.main_photo.files[0],detail=form.detail_photo.files[0];if(!editing&&(!main||!detail)){alert('Choose both a main photo and a detail photo.');return}const input=Object.fromEntries(new FormData(form));input.sizes=[...form.querySelectorAll('input[name="sizes"]:checked')].map(x=>x.value);input.colors=[...form.querySelectorAll('input[name="colors"]:checked')].map(x=>x.value);input.size_guides={};form.querySelectorAll('[data-guide-size]').forEach(field=>{const size=field.dataset.guideSize;if(!input.size_guides[size])input.size_guides[size]={};input.size_guides[size][field.dataset.guideField]=field.value.trim()});input.color_images=editing?.color_images||{};input.colorImageData={};await Promise.all([...form.querySelectorAll('[data-color-photo]')].map(async field=>{if(field.files[0])input.colorImageData[field.dataset.colorPhoto]=await toData(field.files[0])}));input.excludes_charms=Boolean(form.excludes_charms?.checked);input.mainImageData=main?await toData(main):'';input.detailImageData=detail?await toData(detail):'';input.published=form.published.checked;input.featured=form.featured.checked;if(editing){input.image_url=editing.image_url;input.detail_image_url=editing.detail_image_url||''}try{await adminFetch(editing?`/api/admin/products/${editing.id}`:'/api/admin/products',{method:editing?'PATCH':'POST',body:JSON.stringify(input)});state.editId=null;await loadAdmin();render();showAdminSuccess(editing?t('saved'):t('productAdded'))}catch(error){if(error.message!=='Cancelled')alert(error.message)}}
function shop(){const list=state.category==='all'?state.products:state.products.filter(p=>p.category===state.category),hero=state.language==='km'?state.settings.hero_km:state.settings.hero_en,heroText=state.language==='km'?state.settings.hero_text_km:state.settings.hero_text_en;return `<section class="hero"><div class="hero-main"><div class="eyebrow">${t('heroTag')}</div><h1>${hero}</h1><p>${heroText}</p></div><div class="hero-side"><strong>${t('new')}</strong></div></section>${customerActions()}${channelButton()}<div class="section-head"><h2>${t('featured')}</h2><small>${list.length} ${t('items')}</small></div><div class="filters">${['all','clothes','bags','charms'].map(x=>`<button class="filter ${state.category===x?'selected':''}" onclick="setCategory('${x}')">${t(x)}</button>`).join('')}</div><div class="products product-showcase-list">${list.length?list.map(p=>`<article class="product product-showcase"><button class="product-image product-image-button" onclick="showProduct('${p.id}')">${image(p)}</button><div class="showcase-info"><div class="showcase-footer"><h3 class="showcase-name"><button class="title-button" onclick="showProduct('${p.id}')">${productName(p)}</button></h3><div class="showcase-price">${money(p.price)}</div></div></div></article>`).join(''):`<div class="empty">${t('noProducts')}</div>`}</div><button class="cart" onclick="showCart()">${t('bag')} · ${state.cart.reduce((n,x)=>n+x.qty,0)}</button>`}
function settingsAdmin(){const fees=Object.entries(state.settings.shipping||{}).map(([k,v])=>`<div class="settings-row"><span>${k}</span><label>$ <input name="fee-${k}" value="${String(v).replace('$','')}"></label></div>`).join('');return `<div class="panel"><h2>${t('homeTitle')}</h2><form id="settings-form" onsubmit="saveSettings(event)"><label class="field">English headline<input name="hero_en" value="${state.settings.hero_en||''}"></label><label class="field">Khmer headline<input name="hero_km" value="${state.settings.hero_km||''}"></label><label class="field">English introduction<textarea name="hero_text_en">${state.settings.hero_text_en||''}</textarea></label><label class="field">Khmer introduction<textarea name="hero_text_km">${state.settings.hero_text_km||''}</textarea></label><label class="field">${t('pickupAddress')}<input name="pickup" value="${state.settings.pickup||''}"></label><h3>${t('shippingFees')}</h3>${fees}<button class="primary">${t('save')}</button></form></div><div class="panel"><h2>${t('proofAlerts')}</h2><p class="description">${t('proofAlertsHint')}</p><button type="button" class="primary" onclick="connectTelegramOwner()">${t('connectTelegram')}</button></div>`}
